    `,assets:[{type:"image",src:"public/gdsn_img/icons_helvetica/icons.png",caption:"Icon Set"},{type:"image",src:"public/gdsn_img/icons_helvetica/patterns.jpg",caption:"Patterns made from icons"},{type:"image",src:"public/gdsn_img/icons_helvetica/illustration.jpg",caption:"Illustration made from icons"}]},{id:"magazine-fomo",category:"magazine",title:"Magazine: FOMO",duration:"4 weeks",year:"2026",tools:["Adobe Photoshop","Adobe Illustrator","Adobe InDesign"],thumbnail:"public/gdsn_img/magazine_FOMO/mockup2.jpg",description:`
